const samples = await IO.loadMNIST();
const nn = NeuralNet.builder()
    .input(28 * 28)
    .layer(3, NeuralNet.ACTIVATIONS.linear)
    .layer(28 * 28, NeuralNet.ACTIVATIONS.sigmoid)
    .build();

const {theta} = await DataScience.fitDataAsync(samples, samples, nn.model, {
    initialTheta: nn.weightsMap,
    epochs: 1500,
    batch: 8,
    optimizer: DataScience.OPTIMIZERS.ADAMW({learningRate: 0.01}),
    continuationEvery: 100,
    continuationFn: ({epoch, loss}) => console.log(`Batch ${epoch + 1}, reconstruction MSE: ${loss.toFixed(5)}`),
});

const encoder = NeuralNet.builder().input(28 * 28).layer(3, NeuralNet.ACTIVATIONS.linear).build();
encoder.setWeights(theta);
const decoder = NeuralNet.builder().input(3).layer(28 * 28, NeuralNet.ACTIVATIONS.sigmoid).build();
const decoderWeights = Object.fromEntries(Object.entries(theta)
    .filter(([key]) => key.startsWith("W1_") || key.startsWith("b1_"))
    .map(([key, value]) => [key.replace(/^(W|b)1_/, "$10_"), value]));
decoder.setWeights(decoderWeights);

const embeddings = samples.map(sample => encoder.eval(sample));
const coords = Array.from({length: 3}, (_, k) => embeddings.reduce((sum, latent) => sum + latent[k], 0) / embeddings.length);
const decode = latent => Float32Array.from(decoder.eval(latent));
const image = IO.paintMNIST(decode(coords));
const sliders = coords.map((coordinate, k) => {
    const min = Math.min(...embeddings.map(latent => latent[k]));
    const max = Math.max(...embeddings.map(latent => latent[k]));
    return {type: "slider", value: () => ({
        title: `latent_${k + 1}:`, min, max, step: 0.01, value: coordinate,
        onChange: value => {
            coords[k] = value;
            image.update(decode(coords));
        },
    })};
});
const exploreUI = IO.UI({type: "canvas", value: () => image}, ...sliders);
exploreUI;
